-- ============================================================
-- Quiz coverage for databases/oracle and databases/performance-tuning
-- (overview, fundamentals, intermediate, advanced -- all four
-- tabs exist and carry substantive live content for both).
-- Phase 4 (Databases academy), batch 3: Oracle & Performance Tuning.
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- databases/oracle/overview ----------
('databases', 'oracle', 'overview', 'Why does a query like `SELECT SYSDATE FROM DUAL;` need to reference the `DUAL` table at all?', '["DUAL stores the actual system date and must be queried for it", "Oracle requires every SELECT statement to have a FROM clause -- DUAL is a real, one-row table that exists purely to satisfy that requirement for expressions that don''t need to read from an actual table", "DUAL is required only for date functions, not other expressions", "DUAL is a deprecated feature kept only for backward compatibility"]', 1, 'Unlike some other SQL engines that allow SELECT without FROM for a bare expression, Oracle''s syntax requires FROM -- DUAL is the standard workaround, a genuinely one-row table used purely as a placeholder.', 'beginner'),
('databases', 'oracle', 'overview', 'What is a Sequence in Oracle, and why does Oracle need it where PostgreSQL/MySQL don''t require an equivalent explicit step?', '["A sequence is Oracle''s term for a foreign key relationship", "A sequence is an auto-incrementing number generator created explicitly with CREATE SEQUENCE -- unlike PostgreSQL''s BIGSERIAL or MySQL''s AUTO_INCREMENT, which are declared inline on the column itself, Oracle requires the sequence to be created as its own separate object and referenced explicitly via .NEXTVAL", "Sequences are only used for date columns in Oracle", "Sequences automatically enforce uniqueness the same way a UNIQUE constraint does"]', 1, 'This is a genuine syntax/architecture difference worth knowing explicitly -- Oracle historically has no inline auto-increment column type, so generating sequential IDs requires a separate CREATE SEQUENCE object referenced via .NEXTVAL on insert.', 'beginner'),
('databases', 'oracle', 'overview', 'What is the key difference between the old `ROWNUM <= 10` pattern and `ROW_NUMBER() OVER (...) rn` for pagination in Oracle?', '["They are functionally identical with no practical difference", "ROWNUM is assigned to rows BEFORE any ORDER BY in the same query block is applied, so filtering on ROWNUM in a query that also has an ORDER BY doesn''t reliably give you the top N by that order -- ROW_NUMBER() OVER (ORDER BY ...) correctly numbers rows after sorting, making it the reliable modern approach", "ROW_NUMBER() only works in PL/SQL blocks, never in plain SQL", "ROWNUM is faster in every case and should always be preferred"]', 1, 'This is one of the most common Oracle-specific gotchas -- naively combining ROWNUM with ORDER BY in one flat query silently produces the wrong rows unless the ordering happens in an inner subquery first.', 'intermediate'),
('databases', 'oracle', 'overview', 'What does RAC (Real Application Clusters) provide, and what is the more precise way to describe its failover behavior?', '["RAC is Oracle''s backup and restore tool", "RAC lets multiple Oracle instances share the same underlying storage, so if one node fails, the database as a whole stays available and surviving nodes keep serving traffic -- though sessions connected specifically to the failed node still need to reconnect/fail over, so it isn''t literally zero-impact for those sessions", "RAC eliminates the need for any backup strategy", "RAC only works with Oracle Autonomous Database, not on-premises installations"]', 1, 'RAC provides genuinely strong HA at the cluster level, but describing it as \"zero downtime\" overstates the guarantee for the specific sessions connected to the node that actually failed -- precision here matters for accurately setting expectations.', 'intermediate'),
('databases', 'oracle', 'overview', 'In the Oracle architecture, what is the practical difference between the SGA (System Global Area) and the PGA (Program Global Area)?', '["They are two names for the same memory structure", "The SGA is shared memory used by all Oracle background processes and sessions (buffer cache, shared pool, redo log buffer); the PGA is private to each individual session, used for things like sort and hash join work areas", "The PGA is only used during database backups", "The SGA is disk storage, while the PGA is memory"]', 1, 'This shared-vs-private distinction matters for understanding Oracle memory tuning -- SGA sizing affects all sessions collectively, while PGA-related settings affect per-session work like sorting and joining.', 'intermediate'),

-- ---------- databases/oracle/fundamentals ----------
('databases', 'oracle', 'fundamentals', 'What is the purpose of the `/` on its own line after a PL/SQL block''s `END;`?', '["It is a comment marker and has no functional effect", "It tells the SQL client (SQL*Plus, sqlcl) to execute the accumulated PL/SQL block -- unlike a single SQL statement, which a plain semicolon is often enough to trigger, a multi-statement PL/SQL block needs this explicit execute signal", "It marks the end of the entire script file", "It is only required when calling a function, not a procedure"]', 1, 'This is a genuinely common early point of confusion -- forgetting the slash means the block is accumulated in the buffer but never actually executed, even though the syntax looks complete.', 'beginner'),
('databases', 'oracle', 'fundamentals', 'What is the difference between `NVL(expr1, expr2)` and standard SQL''s `COALESCE(expr1, ..., exprN)`?', '["They are completely unrelated functions that do different things", "NVL is Oracle-proprietary and accepts exactly two arguments, replacing NULL with a single fallback value; COALESCE is standard SQL, works across engines, and accepts any number of arguments, returning the first non-NULL one -- for the two-argument case they behave identically", "NVL only works with numeric columns, never strings", "COALESCE is Oracle-specific and NVL is the portable standard-SQL function"]', 1, 'For simple two-value fallbacks they''re interchangeable in Oracle, but COALESCE is the more portable choice, especially when chaining more than two fallback values without nesting NVL calls.', 'beginner'),
('databases', 'oracle', 'fundamentals', 'In a PL/SQL exception handler, what is the practical difference between catching `NO_DATA_FOUND` specifically versus only catching `WHEN OTHERS`?', '["There is no difference -- WHEN OTHERS catches everything NO_DATA_FOUND would", "NO_DATA_FOUND is a specific, predictable exception raised when a SELECT INTO returns zero rows -- handling it explicitly lets you respond precisely to that expected case (e.g. a clear \"not found\" message), while WHEN OTHERS is a catch-all for any exception and loses that specificity unless you also inspect SQLERRM", "WHEN OTHERS can only be used in stored procedures, not anonymous blocks", "NO_DATA_FOUND only applies to DELETE statements"]', 1, 'Catching specific, expected exceptions like NO_DATA_FOUND (and TOO_MANY_ROWS, for a SELECT INTO matching multiple rows) lets error handling be precise about what actually happened, rather than lumping every possible failure into one generic branch.', 'intermediate'),
('databases', 'oracle', 'fundamentals', 'What does `%TYPE` do when declaring a PL/SQL variable, e.g. `v_salary employees.salary%TYPE`?', '["It converts the column to a different data type automatically", "It declares the variable with whatever data type the referenced column (employees.salary) actually has -- so if the column''s type is later changed in the table definition, the variable automatically stays in sync without needing the PL/SQL code to be manually updated", "It creates a new column in the table with that name", "%TYPE only works for NUMBER columns, not other data types"]', 1, 'This is a real maintenance benefit -- hardcoding a variable''s type (e.g. NUMBER(10,2)) risks drifting out of sync if the underlying column''s definition ever changes, while %TYPE stays correct automatically.', 'intermediate'),
('databases', 'oracle', 'fundamentals', 'Why is `SUBSTR('Hello World', 1, 5)` returning `'Hello'` significant to note explicitly for someone coming from a 0-indexed language?', '["It isn''t significant -- all SQL string functions are 0-indexed", "Oracle''s SUBSTR (like most SQL string functions) is 1-indexed, meaning position 1 refers to the first character -- a common source of off-by-one errors for developers used to 0-indexed string slicing in languages like Python or JavaScript", "SUBSTR requires a 4th argument to specify indexing style", "This behavior only applies to VARCHAR2, not CHAR columns"]', 1, 'This 1-indexed convention is standard across SQL string functions generally (not just Oracle), but it''s worth flagging explicitly since it commonly trips up people whose primary programming background uses 0-indexed strings.', 'beginner'),

-- ---------- databases/oracle/intermediate ----------
('databases', 'oracle', 'intermediate', 'What does the `RETURN NUMBER DETERMINISTIC` clause signal on a PL/SQL function, and why does it matter for performance?', '["DETERMINISTIC forces the function to run faster with no other implications", "DETERMINISTIC tells Oracle the function always returns the same output for the same input, allowing Oracle to cache/reuse previous results (e.g. when the function is called repeatedly with the same arguments, or used in a function-based index) rather than re-executing it every time", "DETERMINISTIC is required syntax for every PL/SQL function, not an optional hint", "DETERMINISTIC only affects functions that return VARCHAR2, not NUMBER"]', 1, 'Marking a genuinely pure function as DETERMINISTIC is a real optimization opportunity -- but it should only be used when the function truly has no side effects and always returns the same result for the same input, since Oracle trusts that claim for caching purposes.', 'advanced'),
('databases', 'oracle', 'intermediate', 'What is the practical difference between an implicit cursor (a plain `SELECT ... INTO`) and an explicit cursor (`DECLARE CURSOR ... IS SELECT ...`)?', '["They are functionally identical -- the syntax is purely stylistic", "An implicit cursor is created automatically by Oracle for a single-row SELECT INTO and its state is checked via SQL%FOUND/SQL%NOTFOUND/SQL%ROWCOUNT; an explicit cursor is manually declared, opened, fetched, and closed, and is necessary when a query is expected to return multiple rows that need to be processed one at a time", "Explicit cursors can only be used inside stored procedures, never anonymous blocks", "Implicit cursors are deprecated in current Oracle versions"]', 1, 'The implicit cursor is Oracle''s convenience mechanism for the common single-row SELECT INTO case; an explicit cursor (or the simpler cursor FOR loop) is required once you need to iterate over multiple rows within PL/SQL.', 'intermediate'),
('databases', 'oracle', 'intermediate', 'In a PL/SQL package, what is the practical benefit of declaring a constant like `C_MAX_RAISE CONSTANT NUMBER := 50;` in the package specification rather than hardcoding 50 inside each procedure that uses it?', '["There is no real benefit -- it is purely a style preference", "A package-level constant is defined once and visible to every procedure/function within the package (and to callers, if declared in the spec) -- if the business rule changes, it''s updated in exactly one place rather than hunting down every hardcoded occurrence across multiple procedures", "Constants declared this way are automatically indexed for faster lookup", "Package-level constants can only be NUMBER types, not VARCHAR2 or DATE"]', 1, 'This is a standard software-engineering benefit applied to PL/SQL packages -- centralizing a business-rule value in one place avoids the risk of some procedures using a stale hardcoded value after a change.', 'intermediate'),
('databases', 'oracle', 'intermediate', 'What is the CONNECT BY clause used for, and what genuinely distinguishes it from a recursive CTE (`WITH RECURSIVE`) in PostgreSQL/MySQL?', '["They are identical syntax, just with different keyword names", "CONNECT BY is Oracle''s dedicated syntax for hierarchical (tree-structured) queries -- START WITH defines the root, CONNECT BY PRIOR defines the parent-child relationship -- it has no direct equivalent in PostgreSQL/MySQL, which instead express the same kind of traversal using a recursive CTE''s UNION ALL pattern", "CONNECT BY can only traverse two levels of hierarchy, unlike recursive CTEs", "CONNECT BY is deprecated in favor of recursive CTEs even within Oracle itself"]', 1, 'This is a genuinely Oracle-distinctive feature worth knowing by name specifically because it has no directly equivalent syntax elsewhere -- someone moving from Oracle to PostgreSQL needs to translate CONNECT BY logic into a recursive CTE, not find a one-to-one syntax mapping.', 'advanced'),
('databases', 'oracle', 'intermediate', 'What does `EXCEPTION WHEN OTHERS THEN ROLLBACK; RAISE;` accomplish, and why is the bare `RAISE;` (with no exception name) significant here?', '["RAISE with no argument raises a brand new, generic exception, discarding information about the original error", "RAISE with no argument, inside an exception handler, re-raises the exact original exception that was caught -- this pattern lets the procedure roll back its own work on failure while still propagating the real error information to the caller, rather than swallowing it silently", "This pattern is invalid syntax and would cause a compile error", "ROLLBACK inside an exception handler is not permitted in Oracle PL/SQL"]', 1, 'This is a genuinely important error-handling pattern -- doing local cleanup (ROLLBACK) without silently swallowing the original error means the caller still finds out something went wrong and why, rather than getting a misleadingly successful-looking result.', 'advanced'),

-- ---------- databases/oracle/advanced ----------
('databases', 'oracle', 'advanced', 'Why does Oracle''s partition pruning matter for a range-partitioned table, and how would you confirm it''s actually happening?', '["Partition pruning happens automatically and never needs to be verified", "Partition pruning means a query filtering on the partition key only reads the relevant partition(s) rather than the entire table -- you confirm it''s happening by checking EXPLAIN PLAN output for something like PARTITION RANGE SINGLE rather than a scan across every partition", "Partition pruning only applies to LIST partitioning, not RANGE partitioning", "Partitioning eliminates the need for indexes on the partitioned table entirely"]', 1, 'Confirming pruning with real EXPLAIN PLAN evidence (rather than assuming it works because the table is partitioned) is the actual verification step -- a poorly written query can still scan every partition even on a well-partitioned table.', 'advanced'),
('databases', 'oracle', 'advanced', 'What is the practical difference between Oracle Data Guard''s Physical Standby and Logical Standby?', '["They are the same feature marketed under two different names", "A Physical Standby is a block-for-block exact copy of the primary maintained via Redo Apply; a Logical Standby uses SQL Apply and can have a different physical structure while remaining fully open for queries even during active synchronization -- the tradeoff is between exact fidelity (physical) and query flexibility (logical)", "Logical Standby cannot be used for disaster recovery, only Physical Standby can", "Physical Standby requires manual intervention for every redo record, unlike Logical Standby"]', 1, 'This distinction matters when choosing a DR strategy -- Physical Standby guarantees an exact structural match to the primary, while Logical Standby trades some of that exactness for being continuously queryable without interrupting synchronization.', 'advanced'),
('databases', 'oracle', 'advanced', 'What is the actual difference between a Data Guard "switchover" and a "failover"?', '["They are the same operation performed at different times of day", "A switchover is a planned, deliberate role reversal between primary and standby with no data loss; a failover is an unplanned response to an actual primary failure, which can involve data loss specifically under the Maximum Performance protection mode (asynchronous redo shipping)", "Failover always guarantees zero data loss regardless of protection mode", "Switchover can only be performed by Oracle Support, not database administrators"]', 1, 'The planned-vs-unplanned distinction, and the real data-loss risk difference tied to the protection mode in use, is exactly the kind of practical DR knowledge that matters beyond just knowing Data Guard exists.', 'advanced'),
('databases', 'oracle', 'advanced', 'Why might an optimizer hint like `/*+ INDEX(o idx_orders_customer) */` sometimes make a query slower rather than faster?', '["Hints are purely cosmetic and have no actual effect on execution", "A hint forces the optimizer''s hand regardless of current data distribution or statistics -- if the underlying data or row-count assumptions change over time (e.g. the table grows, or that index stops being selective for the actual query), the hint can force a plan that''s no longer the best choice, while the optimizer''s own default cost-based decision would have adapted automatically", "Hints can only be applied to SELECT statements, never UPDATE or DELETE", "Using a hint always requires rebuilding all indexes on the table first"]', 1, 'This is why hints are a judgment call rather than a default reach -- they override the cost-based optimizer''s adaptive decision-making with something fixed, which can become wrong as data and statistics change over time.', 'advanced'),
('databases', 'oracle', 'advanced', 'What does `RATIO_TO_REPORT(salary) OVER (PARTITION BY department_id)` compute?', '["The salary rank within each department", "For each row, the ratio of that row''s salary to the SUM of all salaries within its department partition -- effectively \"what fraction of this department''s total salary does this employee represent\"", "The percentage change in salary compared to the previous row", "The average salary across the entire table, ignoring the PARTITION BY clause"]', 1, 'RATIO_TO_REPORT is a genuinely Oracle-specific analytic function for exactly this \"share of a group total\" calculation, which in other engines would typically need to be computed manually by dividing by a separate SUM() OVER (PARTITION BY ...) window.', 'advanced'),

-- ---------- databases/performance-tuning/overview ----------
('databases', 'performance-tuning', 'overview', 'Why does the tuning hierarchy place hardware/infrastructure scaling last, rather than first, when addressing a performance problem?', '["Hardware scaling is always more expensive than every other option in absolute dollar terms", "Reaching for bigger hardware before checking for a missing index or a bad query pattern (like an N+1 query) can mask a real inefficiency without ever fixing it -- the underlying problem then resurfaces at the next growth threshold, having cost real ongoing money in the meantime", "Hardware changes require more approval steps than software changes in most organizations", "Modern cloud databases cannot be resized without downtime"]', 1, 'The ordering (schema, query optimization, indexing, configuration, then hardware) reflects that most real performance problems have a cheaper, more durable fix than scaling infrastructure -- hardware is the last resort specifically because it''s expensive and doesn''t address root causes.', 'beginner'),
('databases', 'performance-tuning', 'overview', 'In an EXPLAIN ANALYZE plan showing `Buffers: shared hit=1000 read=50000`, what does the high `read` value specifically indicate?', '["The query returned 50,000 rows to the client", "The query had to read 50,000 blocks from disk rather than finding them already cached in memory (shared buffers) -- a high read count relative to hit count generally signals the working set isn''t fitting in memory for this access pattern", "50,000 is the total execution time in milliseconds", "The value only matters for INSERT/UPDATE statements, not SELECT"]', 1, 'The hit/read distinction in buffer output is a direct signal of how much of the query''s I/O came from cache (fast) versus disk (much slower) -- a query dominated by reads rather than hits is a strong candidate for investigation.', 'intermediate'),
('databases', 'performance-tuning', 'overview', 'Why is `SELECT * FROM customers WHERE id IN (SELECT customer_id FROM orders WHERE status = ''vip'')` often rewritten using `EXISTS` instead?', '["IN and EXISTS always produce different, non-equivalent results", "EXISTS can stop as soon as it finds the first matching row for a given outer row, while IN (subquery) may need to evaluate the full subquery result set to check membership -- for large subqueries this can make EXISTS meaningfully faster, especially when combined with correlation to the outer query", "IN is only valid syntax in MySQL, not PostgreSQL", "EXISTS cannot be used with correlated subqueries"]', 1, 'This EXISTS-stops-at-first-match behavior is why EXISTS is commonly recommended over IN (subquery) specifically for large subqueries, even though both can produce the same logical result for many cases.', 'intermediate'),
('databases', 'performance-tuning', 'overview', 'Why does `WHERE name LIKE ''%widget%''` fail to use a standard B-tree index effectively, unlike `WHERE name LIKE ''widget%''`?', '["LIKE queries never use indexes under any circumstances", "A B-tree index is sorted and searched based on a value''s prefix -- a leading wildcard (%widget%) means there''s no fixed prefix to search from, forcing a full scan, whereas a trailing-only wildcard (widget%) still has a fixed prefix the index can search from directly", "LIKE with % always requires exactly two wildcards to use an index", "This limitation only applies to MySQL, not PostgreSQL"]', 1, 'This is why a leading-wildcard search is a common performance anti-pattern flagged in query rewriting -- the fix is typically a full-text search index (to_tsvector/to_tsquery in PostgreSQL) rather than a standard B-tree index, when genuine substring search is required.', 'intermediate'),
('databases', 'performance-tuning', 'overview', 'What is the practical effect of the N+1 query problem shown by fetching orders then looping to access `order.customer.name` per order?', '["It has no real performance effect since each individual query is fast", "It issues 1 query to fetch the orders plus N additional queries (one per order) to fetch each order''s customer -- the cumulative round-trip latency of N+1 total queries, rather than 1-2 well-formed queries with eager loading, is what causes the real, often severe, slowdown at scale", "It only affects write performance, not read performance", "Eager loading (joinedload) makes the problem worse by fetching too much data at once"]', 1, 'The core issue isn''t that any single query is slow -- it''s the sheer number of round trips, which is why N+1 becomes severe specifically as N (the row count) grows, even though each individual query might look perfectly fine in isolation.', 'beginner'),

-- ---------- databases/performance-tuning/fundamentals ----------
('databases', 'performance-tuning', 'fundamentals', 'What is the real, ongoing cost of adding an index that "just add more indexes" advice ignores?', '["Indexes have no real ongoing cost once created", "Every index must be updated on every INSERT/UPDATE/DELETE that touches an indexed column -- more indexes mean faster reads for the queries they serve, but genuinely slower writes and real additional storage, which is why index strategy is a deliberate tradeoff rather than a \"more is always better\" decision", "Indexes only cost extra storage, never affecting write speed", "The cost of an index is fixed regardless of how many indexes already exist on a table"]', 1, 'This read/write tradeoff is foundational to index strategy -- a table optimized with indexes for every conceivable query pattern will have meaningfully slower write throughput than the same table with a smaller number of well-chosen indexes.', 'beginner'),
('databases', 'performance-tuning', 'fundamentals', 'In an EXPLAIN ANALYZE plan showing `Seq Scan on orders ... Rows Removed by Filter: 99995` for a query matching only 5 rows out of 100,000, what does this specifically indicate?', '["The query returned the wrong results", "The database read and discarded 99,995 rows during a full sequential scan just to find the 5 matching ones -- this is the clear signal that an index on the filtered column is missing, since an index would let the database find those 5 rows directly without scanning the other 99,995", "Rows Removed by Filter always indicates a bug in the query''s WHERE clause", "This output only appears when using EXPLAIN, never EXPLAIN ANALYZE"]', 1, 'A high \"rows removed by filter\" relative to rows actually matched is a very direct, concrete signal (not just a general heuristic) that an index on the filtering column would meaningfully help.', 'intermediate'),
('databases', 'performance-tuning', 'fundamentals', 'Why does a connection pool solve a scaling problem that simply "opening more connections" can''t?', '["Connection pools make individual queries execute faster", "Every database connection consumes real server-side memory/resources independent of whether it''s actively running a query, and there''s a hard max_connections ceiling -- a pool reuses a smaller number of already-established connections rather than opening a new one per request, avoiding both the ceiling and the repeated overhead of connection setup", "Connection pools eliminate the need for a max_connections setting entirely", "Pooling only matters for read queries, not writes"]', 1, 'The key insight is that connections are a genuinely limited, costly resource even when idle -- pooling addresses this by reuse rather than by somehow making connections cheaper individually.', 'beginner'),
('databases', 'performance-tuning', 'fundamentals', 'Why is the N+1 query problem described as "invisible in development" but "severe in production"?', '["Development environments use a completely different query engine than production", "A small test dataset (e.g. 5 orders) produces only 5 extra queries under the N+1 pattern -- imperceptibly fast -- while real production data volume (e.g. 10,000 orders) produces 10,000 extra queries, where the cumulative round-trip latency becomes a severe, user-visible problem that wasn''t apparent during development or testing", "N+1 only occurs when using a specific ORM, never with hand-written SQL", "Production databases are inherently slower than development databases regardless of query pattern"]', 1, 'This scaling-with-N behavior is exactly why N+1 bugs so often ship unnoticed -- the bug is real from the very first line of code, but its cost is proportional to data volume, which is low in development and high in production.', 'intermediate'),
('databases', 'performance-tuning', 'fundamentals', 'Why does the tuning hierarchy list query optimization (EXPLAIN ANALYZE) before index strategy, even though adding an index is often the "quick win"?', '["Query optimization and index strategy are actually the same step under different names", "Understanding what a query is actually doing (via EXPLAIN ANALYZE) is what reveals WHETHER an index would even help and WHICH column(s) it should cover -- adding an index without first understanding the actual query plan risks indexing the wrong thing or missing a query-structure problem (like a correlated subquery) that no index would fix", "Index strategy should always be applied before ever running EXPLAIN ANALYZE", "The order in the hierarchy is arbitrary and has no practical significance"]', 1, 'EXPLAIN ANALYZE is the diagnostic step that informs which fix (a missing index, a query rewrite, or something else) actually applies -- reaching for an index without that diagnosis first is more guesswork than evidence-based tuning.', 'intermediate'),

-- ---------- databases/performance-tuning/intermediate ----------
('databases', 'performance-tuning', 'intermediate', 'What specifically does a covering index (using INCLUDE) let the database avoid, and what does "Index Only Scan" in a plan confirm?', '["It avoids the need for a WHERE clause entirely", "A covering index includes every column the query needs directly in the index, letting the database satisfy the entire query from the index alone without a separate heap-fetch step to retrieve the actual table row -- Index Only Scan in the plan output confirms that heap fetch was genuinely avoided", "Index Only Scan means the query used no index at all", "Covering indexes eliminate the need for the index to be sorted"]', 1, 'The performance win comes specifically from skipping the extra round-trip to the table row -- confirming this actually happened (via Index Only Scan in the plan) rather than assuming it did is the evidence-based habit this course emphasizes throughout.', 'intermediate'),
('databases', 'performance-tuning', 'intermediate', 'Why does a range condition on a non-final column in a composite index "stop the index from being useful for anything after it"?', '["Range conditions are never supported in composite indexes at all", "A B-tree composite index maintains a useful sorted position for columns after an equality condition, but once a range condition (>, <, BETWEEN) is applied, the index can no longer maintain a single useful sorted position for subsequent columns -- so any columns listed after a range-filtered column in the index definition don''t get the same benefit", "This only applies to indexes with more than 5 columns", "The index becomes entirely unusable, even for the columns before the range condition"]', 1, 'This is the mechanical reason behind the "equality columns first, range columns last" rule for composite index column ordering -- it follows directly from how a B-tree''s sorted structure actually works.', 'advanced'),
('databases', 'performance-tuning', 'intermediate', 'Why is partitioning described as something to introduce only "once a table is large enough," rather than proactively on any table that might grow?', '["Partitioning is technically impossible on a table below a certain row count", "Partitioning adds real complexity -- every query needs to consider partition boundaries -- and that complexity only pays off once table/index size itself (not just query selectivity) is genuinely the bottleneck; introducing it prematurely adds cost without a corresponding benefit yet", "Partitioned tables cannot have any indexes", "Partitioning is only supported in PostgreSQL, never other engines"]', 1, 'This mirrors the broader tuning-hierarchy principle: apply a technique when the specific problem it solves is actually present and confirmed, not preemptively based on hypothetical future scale.', 'intermediate'),
('databases', 'performance-tuning', 'intermediate', 'What real-world bug pattern does routing "reads that must reflect a just-completed write back to the primary" specifically prevent?', '["It prevents the primary database from ever failing", "It prevents the scenario where a user submits a form (write to primary), the application immediately redirects to a page reading from a replica, and the just-submitted data appears missing because asynchronous replication hasn''t caught up to the replica yet", "It prevents read replicas from ever going out of sync with the primary", "It only matters for analytics dashboards, not user-facing features"]', 1, 'This is the concrete, common failure mode replication lag causes in practice -- the fix isn''t avoiding replicas altogether, it''s being deliberate about which specific reads need primary-level freshness versus which can tolerate replica lag.', 'intermediate'),
('databases', 'performance-tuning', 'intermediate', 'Why does query result caching (e.g. via Redis with a TTL) introduce a correctness risk that a well-indexed direct query doesn''t have?', '["Caching always returns completely random, unrelated data", "Caching deliberately trades immediate consistency for speed -- the cached value can be stale for up to the TTL duration, which is fine for data that changes infrequently relative to how often it''s requested, but can produce real correctness bugs if applied to something needing to reflect the very latest write, like an account balance or inventory count at checkout", "A well-indexed query is always faster than a cached query", "Caching only works for numeric data types, not text"]', 1, 'The tradeoff is the same shape as replication lag -- deliberately controlled staleness via TTL -- and the same discipline applies: match the caching decision to that specific query''s actual freshness requirement, not apply it uniformly.', 'advanced'),

-- ---------- databases/performance-tuning/advanced ----------
('databases', 'performance-tuning', 'advanced', 'What is the actual difference between a genuine deadlock and general lock contention, and why does that distinction matter for the fix?', '["They are the same thing and require identical fixes", "A true deadlock (a cycle of transactions each waiting on a lock the other holds) is automatically detected and resolved by the database itself via rollback; lock contention that isn''t a true deadlock still causes real queueing delay but requires a different fix -- shorter transactions and consistent lock ordering, not just handling a specific error and retrying", "Lock contention only happens with MyISAM tables, never InnoDB", "Deadlocks can only occur between exactly two transactions, never three or more"]', 1, 'Misdiagnosing contention as a "genuinely slow query" (or vice versa) wastes real investigation time -- the fix for lock-related latency is about transaction design, not query optimization or indexing.', 'advanced'),
('databases', 'performance-tuning', 'advanced', 'Why does a high-write table on PostgreSQL''s default autovacuum settings commonly experience silent, gradually-worsening bloat?', '["Autovacuum is disabled by default and must be manually enabled", "PostgreSQL''s default autovacuum thresholds (like autovacuum_vacuum_scale_factor = 0.2) are tuned conservatively for a generic, lower-write workload -- a genuinely high-write table can accumulate dead tuples faster than the default settings trigger cleanup, causing bloat to grow gradually and silently until query performance visibly degrades", "MVCC only creates dead tuples during DELETE statements, never UPDATE", "Bloat only affects indexes, never the table itself"]', 1, 'The fix isn''t disabling autovacuum''s throttling (which can starve other workloads of I/O) -- it''s tuning the scale factor and cost limit specifically for that table''s actual write volume, often per-table rather than globally.', 'advanced'),
('databases', 'performance-tuning', 'advanced', 'Why would applying OLTP tuning instincts (adding many narrow indexes) to an OLAP data warehouse workload fail to address the actual bottleneck?', '["OLAP workloads cannot use indexes under any circumstances", "OLAP workloads are characterized by few, large queries aggregating across millions of rows -- the typical bottleneck is scan/aggregation throughput and sort/hash memory, not the kind of narrow single-row lookups that OLTP-style selective indexes are designed to accelerate; adding many indexes mostly adds write overhead without addressing that actual bottleneck", "Adding indexes to an OLAP system always makes every query faster with no downside", "OLTP and OLAP workloads have identical performance characteristics"]', 1, 'Recognizing which category a workload actually falls into -- and tuning accordingly, potentially including a columnar storage engine for genuine OLAP needs -- is treated as a foundational architectural decision, not a later tuning detail.', 'advanced'),
('databases', 'performance-tuning', 'advanced', 'Why is sharding described as "the last resort" rather than an early architectural default, despite being genuinely the most powerful scaling technique available?', '["Sharding is technically impossible to implement correctly", "Sharding is also the most operationally expensive option -- cross-shard queries become significantly more complex, and rebalancing unevenly-growing shards is a real, ongoing burden -- a well-chosen index, a fixed N+1 query, or proper autovacuum tuning routinely delivers a larger, cheaper performance win before sharding''s costs are ever justified", "Sharding can only be used with NoSQL databases, never relational ones", "Sharding automatically eliminates the need for any indexing strategy"]', 1, 'This is a direct application of the tuning hierarchy''s core principle: reach for the most operationally expensive fix only once cheaper, lower-cost options are genuinely exhausted and confirmed insufficient, not as a first architectural instinct.', 'advanced'),
('databases', 'performance-tuning', 'advanced', 'When diagnosing lock waits with a query joining pg_locks and pg_stat_activity, why does the join condition include `blocking_locks.pid != blocked_locks.pid`?', '["It is unnecessary and could be removed without changing the results", "Without excluding a lock row from matching itself, a session''s own granted lock would incorrectly appear to be \"blocking\" its own not-yet-granted lock request on the same locktype, producing false self-blocking results instead of showing genuine blocking from a different session", "This condition filters out all locks except row-level locks", "PID comparisons are only needed in MySQL, not PostgreSQL"]', 1, 'This is a real detail worth understanding rather than just copy-pasting the diagnostic query -- without it, the query could misreport a session as blocked by itself, obscuring the actual blocking session.', 'advanced');
